static const int database_size = 29845;

// Helper: normalize postal code (remove spaces, uppercase)
static void normalize_code(const char *input, char *output, int max_len) {
    int j = 0;
    for (int i = 0; input[i] && j < max_len - 1; i++) {
        if (input[i] != ' ' && input[i] != '-') {
            output[j++] = (input[i] >= 'a' && input[i] <= 'z') ? input[i] - 32 : input[i];
        }
    }
    output[j] = '\0';
}

// Helper: check if a ZIP code falls within a range
// Returns true if code matches "12345" or falls in range "12000-12999"
static bool code_in_range(const char *search_code, const char *db_code) {
    // Check for exact match first (fast path)
    char norm_search[32], norm_db[32];
    normalize_code(search_code, norm_search, sizeof(norm_search));
    normalize_code(db_code, norm_db, sizeof(norm_db));

    if (strcmp(norm_search, norm_db) == 0) {
        return true;
    }

    // Check if db_code contains a range (has '-')
    const char *dash = strchr(db_code, '-');
    if (!dash) {
        return false;  // Not a range, no match
    }

    // Parse range: "10001-10292"
    char min_code[32], max_code[32];
    int dash_pos = dash - db_code;
    strncpy(min_code, db_code, dash_pos);
    min_code[dash_pos] = '\0';
    strcpy(max_code, dash + 1);

    // Try to convert to integers for numeric comparison
    char *endptr;
    long search_num = strtol(search_code, &endptr, 10);
    if (*endptr != '\0') {
        return false;  // Not a valid number
    }

    long min_num = strtol(min_code, &endptr, 10);
    if (*endptr != '\0') {
        return false;
    }

    long max_num = strtol(max_code, &endptr, 10);
    if (*endptr != '\0') {
        return false;
    }

    // Check if in range
    return (search_num >= min_num && search_num <= max_num);
}

// Find exact postal code match (supports ranges)
const postal_code_entry_t* find_postal_code(const char *code) {
    if (!code) return NULL;

    for (int i = 0; i < database_size; i++) {
        if (code_in_range(code, postal_code_database[i].code)) {
            return &postal_code_database[i];
        }
    }

    return NULL;
}

// Find postal code with fuzzy matching (prefix match + range support)
const postal_code_entry_t* find_postal_code_fuzzy(const char *code) {
    if (!code || strlen(code) < 2) return NULL;

    // First try exact/range match
    const postal_code_entry_t *exact = find_postal_code(code);
    if (exact) return exact;

    // Try prefix match
    char normalized[32];
    normalize_code(code, normalized, sizeof(normalized));
    int len = strlen(normalized);

    for (int i = 0; i < database_size; i++) {
        char db_normalized[32];
        normalize_code(postal_code_database[i].code, db_normalized, sizeof(db_normalized));

        if (strncmp(normalized, db_normalized, len) == 0) {
            return &postal_code_database[i];
        }
    }

    return NULL;
}

// Unified search - searches BOTH postal codes AND city names
const postal_code_entry_t* find_location_unified(const char *search_text) {
    if (!search_text || strlen(search_text) < 2) return NULL;

    // Normalize search text
    char normalized[64];
    int j = 0;
    for (int i = 0; search_text[i] && j < 63; i++) {
        char c = search_text[i];
        if (c >= 'a' && c <= 'z') c = c - 32;
        if (c != ' ' || (j > 0 && normalized[j-1] != ' ')) {
            normalized[j++] = c;
        }
    }
    if (j > 0 && normalized[j-1] == ' ') j--;
    normalized[j] = '\0';

    int search_len = strlen(normalized);
    if (search_len < 2) return NULL;

    // Priority 1: Try postal code match first (with range support)
    const postal_code_entry_t *postal_match = find_postal_code_fuzzy(search_text);
    if (postal_match) return postal_match;

    // Priority 2: Search city names
    for (int i = 0; i < database_size; i++) {
        const postal_code_entry_t *entry = &postal_code_database[i];

        char searchable[128];
        snprintf(searchable, sizeof(searchable), "%s %s", entry->city, entry->state);

        for (int k = 0; searchable[k]; k++) {
            if (searchable[k] >= 'a' && searchable[k] <= 'z') {
                searchable[k] = searchable[k] - 32;
            }
        }

        if (strstr(searchable, normalized) != NULL) {
            return entry;
        }
    }

    return NULL;
}

// Count matches
int count_location_matches(const char *search_text) {
    if (!search_text || strlen(search_text) < 2) return 0;

    char normalized[64];
    int j = 0;
    for (int i = 0; search_text[i] && j < 63; i++) {
        char c = search_text[i];
        if (c >= 'a' && c <= 'z') c = c - 32;
        if (c != ' ' || (j > 0 && normalized[j-1] != ' ')) {
            normalized[j++] = c;
        }
    }
    if (j > 0 && normalized[j-1] == ' ') j--;
    normalized[j] = '\0';

    int search_len = strlen(normalized);
    if (search_len < 2) return 0;

    int match_count = 0;

    // Count postal code matches (including ranges)
    for (int i = 0; i < database_size && match_count < 100; i++) {
        if (code_in_range(search_text, postal_code_database[i].code)) {
            match_count++;
            continue;
        }

        char db_normalized[32];
        normalize_code(postal_code_database[i].code, db_normalized, sizeof(db_normalized));
        if (strncmp(normalized, db_normalized, search_len) == 0) {
            match_count++;
        }
    }

    // Count city name matches
    for (int i = 0; i < database_size && match_count < 100; i++) {
        char searchable[128];
        snprintf(searchable, sizeof(searchable), "%s %s",
                 postal_code_database[i].city, postal_code_database[i].state);

        for (int k = 0; searchable[k]; k++) {
            if (searchable[k] >= 'a' && searchable[k] <= 'z') {
                searchable[k] = searchable[k] - 32;
            }
        }

        if (strstr(searchable, normalized) != NULL) {
            match_count++;
        }
    }

    return match_count > 100 ? 100 : match_count;
}

// Get database size
int get_postal_code_count(void) {
    return database_size;
}

// Get attribution text
const char* get_postal_code_attribution(void) {
    return "Postal code data from GeoNames (www.geonames.org)";
}

// ========== Hierarchical Location Browsing ==========

// Get number of unique countries in database
int get_unique_country_count(void) {
    int count = 0;
    const char *last_country = NULL;

    for (int i = 0; i < database_size; i++) {
        const char *country = postal_code_database[i].country;
        if (last_country == NULL || strcmp(country, last_country) != 0) {
            count++;
            last_country = country;
        }
    }
    return count;
}

// Get unique country by index (USA first, Canada second, then alphabetically)
const char* get_unique_country(int index) {
    // Priority countries
    if (index == 0) return "United States";
    if (index == 1) return "Canada";

    // Get remaining countries alphabetically
    int count = 2;  // Start after USA and Canada
    const char *last_country = NULL;

    for (int i = 0; i < database_size; i++) {
        const char *country = postal_code_database[i].country;
        if (last_country == NULL || strcmp(country, last_country) != 0) {
            // Skip USA and Canada (already handled)
            if (strcmp(country, "United States") == 0 || strcmp(country, "Canada") == 0) {
                last_country = country;
                continue;
            }

            if (count == index) {
                return country;
            }
            count++;
            last_country = country;
        }
    }
    return NULL;
}

// Get number of unique states for a country
int get_unique_state_count(const char *country) {
    if (!country) return 0;

    int count = 0;
    const char *last_state = NULL;

    for (int i = 0; i < database_size; i++) {
        if (strcmp(postal_code_database[i].country, country) == 0) {
            const char *state = postal_code_database[i].state;
            // Skip empty states
            if (state[0] == '\0') continue;

            if (last_state == NULL || strcmp(state, last_state) != 0) {
                count++;
                last_state = state;
            }
        }
    }
    return count;
}

// Get unique state for a country by index
const char* get_unique_state(const char *country, int index) {
    if (!country) return NULL;

    int count = 0;
    const char *last_state = NULL;

    for (int i = 0; i < database_size; i++) {
        if (strcmp(postal_code_database[i].country, country) == 0) {
            const char *state = postal_code_database[i].state;
            // Skip empty states
            if (state[0] == '\0') continue;

            if (last_state == NULL || strcmp(state, last_state) != 0) {
                if (count == index) {
                    return state;
                }
                count++;
                last_state = state;
            }
        }
    }
    return NULL;
}

// Get number of unique cities for a country/state combination
int get_unique_city_count(const char *country, const char *state) {
    if (!country) return 0;

    int count = 0;
    const char *last_city = NULL;

    for (int i = 0; i < database_size; i++) {
        const postal_code_entry_t *entry = &postal_code_database[i];

        // Match country
        if (strcmp(entry->country, country) != 0) continue;

        // Match state (if provided and non-empty in database)
        if (state && state[0] != '\0' && entry->state[0] != '\0') {
            if (strcmp(entry->state, state) != 0) continue;
        }

        const char *city = entry->city;
        if (last_city == NULL || strcmp(city, last_city) != 0) {
            count++;
            last_city = city;
        }
    }
    return count;
}

// Get unique city entry for a country/state combination by index
const postal_code_entry_t* get_unique_city(const char *country, const char *state, int index) {
    if (!country) return NULL;

    int count = 0;
    const char *last_city = NULL;

    for (int i = 0; i < database_size; i++) {
        const postal_code_entry_t *entry = &postal_code_database[i];

        // Match country
        if (strcmp(entry->country, country) != 0) continue;

        // Match state (if provided and non-empty in database)
        if (state && state[0] != '\0' && entry->state[0] != '\0') {
            if (strcmp(entry->state, state) != 0) continue;
        }

        const char *city = entry->city;
        if (last_city == NULL || strcmp(city, last_city) != 0) {
            if (count == index) {
                return entry;
            }
            count++;
            last_city = city;
        }
    }
    return NULL;
}
